// --- Issue #1: the ball must bounce off bricks, not plow through -----------

// A context stub: every method is a no-op, property writes are accepted.
// Lets us exercise the render pass (where brick collisions are resolved)
// without a canvas.
function noopCtx() {
  return new Proxy(
    {},
    {
      get(target, prop) {
        if (!(prop in target)) target[prop] = () => {};
        return target[prop];
      },
      set(target, prop, value) {
        target[prop] = value;
        return true;
      },
    }
  );
}

// Brick #0 spans [4..76] x [48..68] and its right neighbour #1 starts at 84
// (the grid gap is 8 px, the ball 14 px across — seams overlap two bricks).

// per face (top): flip vy, leave vx alone, push the ball back out.
test('brickBounce: top hit flips vy only and pushes the ball out', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball = { x: brick.x + brick.w / 2, y: brick.y - BALL_R + 4, r: BALL_R, vx: 30, vy: 200 };
  brickBounce(state);
  assert.equal(brick.alive, false);
  assert.equal(state.ball.vy, -200, 'vy flips on a top hit');
  assert.equal(state.ball.vx, 30, 'vx left exactly as it was');
  assert.ok(state.ball.y + state.ball.r < brick.y, 'ball pushed out above the brick');
  assert.equal(collides(state.ball, brick), false, 'no overlap remains (no sticky bounce)');
  assert.equal(state.combo, 1, 'combo still increments per brick');
});

// per face (side): flip vx, leave vy alone, push the ball back out.
test('brickBounce: side hit flips vx only and pushes the ball out', () => {
  const state = createState(1);
  const brick = state.bricks[3]; // col 3, clear of the side walls
  state.ball = { x: brick.x - BALL_R - 3, y: brick.y + brick.h / 2, r: BALL_R, vx: 200, vy: 0 };
  step(state, 1 / 20); // moves 10 px: the ball now overlaps the left face
  const hits = brickBounce(state);
  assert.equal(hits.length, 1, 'only the brick actually reached is hit');
  assert.equal(brick.alive, false);
  assert.equal(state.ball.vx, -200, 'vx flips on a side hit');
  assert.equal(state.ball.vy, 0, 'vy left exactly as it was');
  assert.ok(state.ball.x - state.ball.r > brick.x + brick.w, 'ball pushed out right of the brick');
  assert.equal(collides(state.ball, brick), false);
});

// corner: equal penetrations on two perpendicular faces => flip both.
test('brickBounce: equal penetrations (corner) flip both components', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  // 1 px into the top face, 1 px into the left face: a diagonal hit.
  state.ball = { x: brick.x - BALL_R + 1, y: brick.y - BALL_R + 1, r: BALL_R, vx: 200, vy: 200 };
  brickBounce(state);
  assert.equal(brick.alive, false);
  assert.equal(state.ball.vx, -200);
  assert.equal(state.ball.vy, -200);
  assert.equal(collides(state.ball, brick), false);
});

// neighbours: a seam (8 px gap < 14 px ball) overlaps two bricks in the same
// pass — the bounce must apply exactly once, not once per brick.
test('brickBounce: a seam hit bounces exactly once, not once per brick', () => {
  const state = createState(1);
  const a = state.bricks[0];
  const b = state.bricks[1];
  const gapCenter = a.x + a.w + (b.x - (a.x + a.w)) / 2; // middle of the seam
  state.ball = { x: gapCenter, y: a.y - BALL_R - 20, r: BALL_R, vx: 0, vy: 500 };
  step(state, 0.05); // 25 px down, into both bricks at the same instant
  const hits = brickBounce(state);
  assert.equal(hits.length, 2, 'both bricks of the seam go down');
  assert.equal(a.alive, false);
  assert.equal(b.alive, false);
  assert.equal(state.ball.vy, -500, 'flipped exactly once (a double flip cancels out)');
  assert.equal(state.ball.vx, 0);
  assert.equal(state.combo, 2, 'combo counts both bricks');
  assert.equal(collides(state.ball, a), false);
  assert.equal(collides(state.ball, b), false);
});

// tunnelling: at level 6 a 50 ms frame moves the ball 35.5 px, more than the
// 34 px needed to cross a brick — the swept test must catch the jump-over.
test('brickBounce: a fast ball cannot tunnel through a brick', () => {
  const state = createState(6);
  const brick = state.bricks[(BRICK_ROWS - 1) * BRICK_COLS]; // bottom row
  state.ball = { x: brick.x + brick.w / 2, y: brick.y + brick.h + BALL_R + 1, r: BALL_R, vx: 0, vy: -710 };
  step(state, 0.05); // 35.5 px up: starts below, ends above
  assert.ok(
    state.ball.y + state.ball.r < brick.y,
    'sanity: the endpoints never overlap — only a sweep can catch this'
  );
  const hits = brickBounce(state);
  assert.equal(hits.length, 1);
  assert.equal(brick.alive, false);
  assert.ok(state.ball.vy > 0, 'flipped back down');
  assert.ok(state.ball.y - state.ball.r > brick.y + brick.h, 'pushed out below the brick');
});

// The visible symptom: frame() (the render pass) must actually deflect.
test('frame: the render pass bounces the ball off bricks', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball = { x: brick.x + brick.w / 2, y: brick.y - BALL_R + 4, r: BALL_R, vx: 30, vy: 200 };
  frame(noopCtx(), state);
  assert.equal(brick.alive, false);
  assert.equal(state.ball.vy, -200);
  assert.equal(state.ball.vx, 30);
});

// Small local helper: place the ball below the field without importing the
// height (coverage intentionally light).
function belowField() {
  return 500;
}

