+function noopCtx() {
+  return new Proxy(
+    {},
+    {
+      get(target, prop) {
+        if (!(prop in target)) target[prop] = () => {};
+        return target[prop];
+      },
+      set(target, prop, value) {
+        target[prop] = value;
+        return true;
+      },
+    }
+  );
+}
