// --- Brick collisions (issue #1) -------------------------------------------
//
// The ball must bounce off bricks like off the walls, face by face. Detection
// is discrete (position before / after the move), so the resolution works on
// the *swept* segment: at level 6 one frame moves the ball 35.5 px against the
// 34 px needed to cross a brick, and a point-in-rect test alone would jump
// over it. And because the grid gap is 8 px against a 14 px ball, every seam
// overlaps two bricks in the same pass: the bounce must apply exactly once
// (a `vy = -vy` applied twice cancels out and the ball goes straight through).

// Earliest time t in [0, 1] at which the ball's box (radius `r`, centre
// sweeping from (x0, y0) along (dx, dy)) first touches the brick's expanded
// box [brick.x - r, brick.x + brick.w + r] x [brick.y - r, brick.y + brick.h + r].
// Returns null when the swept path misses the brick entirely.
function sweptEntry(x0, y0, dx, dy, brick, r) {
  const x1 = brick.x - r;
  const x2 = brick.x + brick.w + r;
  const y1 = brick.y - r;
  const y2 = brick.y + brick.h + r;

  let tEnter = 0;
  let tExit = 1;

  // X slab.
  if (dx === 0) {
    if (x0 < x1 || x0 > x2) return null;
  } else {
    let a = (x1 - x0) / dx;
    let b = (x2 - x0) / dx;
    if (a > b) {
      const tmp = a;
      a = b;
      b = tmp;
    }
    tEnter = Math.max(tEnter, a);
    tExit = Math.min(tExit, b);
  }

  // Y slab.
  if (dy === 0) {
    if (y0 < y1 || y0 > y2) return null;
  } else {
    let a = (y1 - y0) / dy;
    let b = (y2 - y0) / dy;
    if (a > b) {
      const tmp = a;
      a = b;
      b = tmp;
    }
    tEnter = Math.max(tEnter, a);
    tExit = Math.min(tExit, b);
  }

  // Reached this step only if the box enters before t = 1 and has not fully
  // left before t = 0. Clamp to 0: an overlap already present at the start of
  // the move counts as a hit right away.
  if (tEnter > tExit || tEnter > 1 || tExit < 0) return null;
  return Math.max(0, tEnter);
}

// How far past the face the ball is pushed back out: a position merely tangent
// to the brick still overlaps (within float error) on the next frame and
// re-flips forever — the sticky bounce.
const PUSH_OUT = 0.01;
// Two penetrations this close on perpendicular axes are a corner hit.
const PEN_TIE = 1e-6;
// Two bricks entered this close in time were hit at the same instant (a seam).
const SAME_INSTANT = 1e-6;

// Resolves every ball/brick contact of one frame: destroys the bricks hit at
// the earliest contact, scores them, bounces the ball off the face it entered
// (flipping exactly that axis — or both on a corner — and nothing else), then
// pushes the ball back outside the bricks. All bricks entered at the same
// instant are grouped and bounce once, as a single wall (seam-safe).
// Returns the array of bricks that were hit.
export function brickBounce(state) {
  const { ball, bricks } = state;

  // The segment travelled this step (previous position recorded by step()).
  // Without a previous position (fresh ball, direct call), fall back to a
  // zero-length segment: overlap is still caught.
  const x0 = Number.isFinite(ball.prevX) ? ball.prevX : ball.x;
  const y0 = Number.isFinite(ball.prevY) ? ball.prevY : ball.y;
  const dx = ball.x - x0;
  const dy = ball.y - y0;

  // Sweep every live brick and keep the earliest contact of this frame.
  let bestT = Infinity;
  let hits = [];
  for (const brick of bricks) {
    if (!brick.alive) continue;
    const t = sweptEntry(x0, y0, dx, dy, brick, ball.r);
    if (t === null) continue;
    if (t < bestT - SAME_INSTANT) {
      bestT = t;
      hits = [brick];
    } else if (t <= bestT + SAME_INSTANT) {
      hits.push(brick);
    }
  }
  if (hits.length === 0) return [];

  // One scoring pass for the whole group.
  for (const brick of hits) {
    brick.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(brick, state.combo);
  }

  // The union of the group's rectangles: a seam behaves like a single wall.
  let minX = Infinity;
  let minY = Infinity;
  let maxX = -Infinity;
  let maxY = -Infinity;
  for (const brick of hits) {
    if (brick.x < minX) minX = brick.x;
    if (brick.y < minY) minY = brick.y;
    if (brick.x + brick.w > maxX) maxX = brick.x + brick.w;
    if (brick.y + brick.h > maxY) maxY = brick.y + brick.h;
  }

  // Rewind to the moment of first contact, then read the face from the
  // penetration depths there: the axis with the smaller penetration is the
  // face that was hit, and two equal (perpendicular) penetrations mean a
  // diagonal hit — flip both components.
  ball.x = x0 + bestT * dx;
  ball.y = y0 + bestT * dy;

  const penLeft = ball.x + ball.r - minX;
  const penRight = maxX - (ball.x - ball.r);
  const penTop = ball.y + ball.r - minY;
  const penBottom = maxY - (ball.y - ball.r);

  const faces = [
    { axis: 'x', dir: LEFT, pen: penLeft },
    { axis: 'x', dir: RIGHT, pen: penRight },
    { axis: 'y', dir: UP, pen: penTop },
    { axis: 'y', dir: DOWN, pen: penBottom },
  ].sort((a, b) => a.pen - b.pen);

  const face = faces[0];
  const second = faces[1];
  const corner = second.axis !== face.axis && second.pen - face.pen <= PEN_TIE;

  if (face.axis === 'x') ball.vx = -ball.vx;
  else ball.vy = -ball.vy;
  if (corner) {
    if (second.axis === 'x') ball.vx = -ball.vx;
    else ball.vy = -ball.vy;
  }

  // Push the ball back out, beyond the face(s) it hit.
  const outX = (dir) => (dir === LEFT ? minX - ball.r - PUSH_OUT : maxX + ball.r + PUSH_OUT);
  const outY = (dir) => (dir === UP ? minY - ball.r - PUSH_OUT : maxY + ball.r + PUSH_OUT);
  if (face.axis === 'x') ball.x = outX(face.dir);
  else ball.y = outY(face.dir);
  if (corner) {
    if (second.axis === 'x') ball.x = outX(second.dir);
    else ball.y = outY(second.dir);
  }

  return hits;
}

