// Main render loop. Brick collision resolution (destroy + score + bounce) is
// delegated to `brickBounce`, still invoked from the render pass: logic and
// rendering remain entangled (debt #2), but the bounce itself is fixed (#1).
export function frame(ctx, state) {
  // Background
  ctx.fillStyle = palette.background;
  ctx.fillRect(0, 0, WIDTH, HEIGHT);

  // Bricks: resolve collisions for this frame, then draw what is left.
  brickBounce(state);

  for (const brick of state.bricks) {
    if (!brick.alive) continue;
    ctx.fillStyle = brickColor(brick.row);
    ctx.fillRect(brick.x, brick.y, brick.w, brick.h);
  }

